/**
 * The panel of the active step of StoryTabs: the year badge and the step count, the title, the text and the tag
 * in a muted box.
 */
import { type JSX } from "solid-js";
import { Badge } from "../primitives/badge/badge";
import { Box } from "../primitives/box/box";
import { Group } from "../primitives/group/group";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { tpl } from "../utils";
import type { Milestone } from "../blocks/milestone-timeline.types";
import type { StoryLabels } from "../blocks/story-tabs.types";

export type StoryPanelProps = {
  s: Milestone;
  index: number;
  total: number;
  labels: StoryLabels;
};

export function StoryPanel({ s, index, total, labels }: StoryPanelProps) {
  return (
    <Stack
      gap="4"
      align="stretch"
      class="rounded bg-card inset-ring inset-ring-border p-6"
      data-testid="story-panel"
    >
      <Group gap="2" align="center">
        <Badge variant="secondary" size="sm">
          {s.date}
        </Badge>
        <Text size="xs" class="text-muted-foreground">
          {tpl(labels.step, ((index + 1) == null ? undefined : String((index + 1))), (total == null ? undefined : String(total)))}
        </Text>
      </Group>
      <Title as={3} size="xl" weight="semibold">
        {s.title}
      </Title>
      <Text size="sm" class="text-muted-foreground">
        {s.text}
      </Text>
      <Box class="rounded bg-muted p-4">
        <Text size="sm" weight="semibold">
          {s.tag}
        </Text>
      </Box>
    </Stack>
  );
}
